from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # offline_until stores the timestamp when a user will be back online
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp. If timestamps are equal, OFFLINE must come first.
    # We use a tuple (timestamp, type_priority, original_index) to ensure stability.
    # Since "OFFLINE" status changes happen before "MESSAGE", we prioritize them.
    sorted_events = []
    for i, e in enumerate(events):
        ts = int(e[1])
        priority = 0 if e[0] == "OFFLINE" else 1
        sorted_events.append((ts, priority, e))

    # Sort by timestamp first, then by type priority
    sorted_events.sort()

    for _, _, event in sorted_events:
        etype = event[0]
        if etype == "OFFLINE":
            uid = int(event[2][2:]) # Extract number from "idX"
            offline_until[uid] = int(event[1]) + 60
        else:
            content = event[2]
            tokens = content.split()
            for token in tokens:
                if token == "ALL":
                    for i in range(numberOfUsers):
