```python
from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[k][i][j] 表示到達 (i, j) 且已使用 k 次中和能力的最大收益
    # 使用三個矩陣來節省空間（或直接用一個三維陣列，這裡為了清晰用三維）
    # 初始化為極小值
    INF = float('inf')
    dp = [[[-INF] * n for _ in range(m)] for _ in range(3)]

    # 起點初始化
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        dp[0][0][0] = val # 沒用中和，被搶走
        dp[1][0][0] = 0   # 用了一次中和，變成 0
        # 注意：如果起點是負數且只能中和2次，這裡邏輯會自動處理

    for k in range(3):
        for i in range(m):
            for j in range(n):
                if dp[k][i][j] == -INF: continue

                # 向右走或向下走
                for di, dj in [(0, 1), (1, 0)]:
                    ni, nj = i + di, j + dj
                    if ni < m and nj < n:
                        current_val = coins[ni][nj]

                        # 選項 1: 不使用中和能力（或該格子本來就是正數）
                        dp[k][ni][nj] = max(dp[k][ni][nj], dp[k][i][j] + current_val)

                        # 選項 2: 如果還有中和次數且該格子是負數，嘗試使用中和能力
                        if k < 2 and current_val < 0:
                            dp[k+1][ni][nj] = max(dp[k+1][ni][nj], dp[k][i][j])

    # 因為起點可能就是負數且被中和了，我們需要處理起始狀態的正確性
    # 重新簡化邏輯：
    # 實際上最簡單的做法是：
    # dp[k][i][j] = 最大收益，k 為已使用的中和次數 (0, 1, 2)

    dp = [[[-INF] * n for _ in range(m)] for _ in range(3)]

    # 起點處理
    v0 = coins[0][0]
    if v0 >= 0:
        dp[0][0][0] = v0
    else:
        dp[0][0][0] = v0
        dp[1][0][0] = 0

    for i in range(m):
        for j in range(n):
            for k in range(3):
                if dp[k][i][j] == -INF: continue

                for di, dj in [(0, 1), (1, 0)]:
                    ni, nj = i + di, j + dj
                    if ni < m and nj < n:
                        val = coins[ni][nj]
                        # 不用中和能力
                        dp[k][ni][nj] = max(dp[k][ni][nj], dp[k][i][j] + val)
                        # 用中和能力 (僅限負數)
                        if k < 2 and val < 0:
                            dp[k+1][ni][nj] = max(dp[k+1][ni][nj], dp[k][i][j])

    return max(dp[0][m-1][n-1], dp[1][m-1][n-1], dp[2][m-1][n-1])
```

