from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # 建立所有可能的 prefix 集合 (用 set 取優化查詢速度)
    prefixes = set()
    for w in words:
        for i in range(1, len(w) + 1):
            prefixes.add(w[:i])

    n = len(target)
    # dp[i] 表示組成 target 前 i 個字元的最小數量
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue
        # 從當前位置往後嘗試所有可能的 prefix 長度
        # 因為 target 長度上限 5000，這裡用迴圈檢查 prefixes 是否存在
        for j in range(i + 1, n + 1):
            if target[i:j] in prefixes:
                dp[j] = min(dp[j], dp[i] + 1)
            else:
                # 如果當前長度的 substring 不在 prefix 中，更長的也不可能直接匹配
                # 但因為是 "prefix of any string"，必須繼續檢查直到目標邊界或找到匹配
                pass

    return dp[n] if dp[n] != float('inf') else -1
