    n = len(word)

    # 因為 word.length 只有 250，使用 O(n^2) 的雙重迴圈即可通過
    for i in range(n):
        current_vowels = set()
        consonants = 0
        for j in range(i, n):
            char = word[j]
            if char in vowels:
                current_vowels.add(char)
            else:
                consonants += 1

            # 如果子字串包含所有 5 個母音且輔音數量剛好為 k，則計數
            if len(current_vowels) == 5 and consonants == k:
                count += 1

            # 若輔音已經超過 k，後續的子字串也不可能符合條件（因為輔音數只會增加）
            if consonants > k:
                break

    return count
