```python
from typing import List

def maximumWeight(intervals: List[List[int]]) -> List[int]:
    # 儲存原始索引：(left, right, weight, original_index)
    data = []
    for i, (l, r, w) in enumerate(intervals):
        data.append((l, r, w, i))

    # 按左端點排序，若相同按右端點排序
    data.sort()
    n = len(data)

    # 預處理：對於每個區間 i，找到第一個與它不重疊的區間 j (data[j].left > data[i].right)
    next_idx = [n] * n
    j = 0
    for i in range(n):
        while j < n and data[j][0] <= data[i][1]:
            j += 1
        next_idx[i] = j

    # dp[k][i] = (max_weight, [indices]) 
    # 表示從第 i 個區間開始，選取最多 k 個不重疊區間的結果
    # 使用 list 儲存 dp 以節省空間，並由後往前計算
    dp = [[(0, []) for _ in range(n + 1)] for _ in range(5)]

    # 從 1 到 4 個區間進行 DP
    for k in range(1, 5):
        for i in range(n - 1, -1, -1):
            # 選取當前區間 data[i]
            current_w = data[i][2]
            next_i = next_idx[i]
            sub_w, sub_indices = dp[k-1][next_i]
            res_w = current_w + sub_w
            res_indices = [data[i][3]] + sub_indices

            # 不選取當前區間 data[i]
            skip_w, skip_indices = dp[k][i+1]

            if res_w > skip_w:
                dp[k][i] = (res_w, res_indices)
            elif res_w == skip_w:
                # 比較字典序：較短的或較小的索引優先
                if len(res_indices) < len(skip_indices):
                    dp[k][i] = (res_w, res_indices)
                elif len(res_indices) > len(skip_indices):
                    dp[k][i] = (res_w, skip_indices)
                else:
                    if res_indices < skip_indices:
                        dp[k][i] = (res_w, res_indices)
                    else:
                        dp[k][i] = (res_w, skip_indices)
            else:
                dp[k][i] = (skip_w, skip_indices)

    # 最後找出所有 k 在 1~4 之間的結果中，權重最大且字典序最小的
    max_total_w = -1
    best_res = []

    for k in range(1, 5):
        for i in range(n):
            w, indices = dp[k][i]
            if w > max_total_w:
                max_total_w = w
                best_res = indices
            elif w == max_total_w:
                if not best_res or indices < best_res:
                    best_res = indices

    return best_res
