def generateString(str1: str, str2: str) -> str:
    n, m = len(str1), len(str2)
    res = [None] * (n + m - 1)

    # 填入 T
    for i in range(n):
        if str1[i] == 'T':
            for j in range(m):
                if res[i+j] is not None and res[i+j] != str2[j]: return ""
                res[i+j] = str2[j]

    # 填入剩餘位置 (貪婪法)
    for i in range(n + m - 1):
        if res[i] is None:
            for char_code in range(ord('a'), ord('z') + 1):
                c = chr(char_code)
                res[i] = c
                # 檢查是否造成任何 F 被違反
                possible = True
                for k in range(max(0, i - m + 1), min(n, i + 1)):
                    if str1[k] == 'F':
                        # 如果該位置的 substring 可能等於 str2，則不允許
                        is_match = True
                        all_fixed = True
                        for j in range(m):
                            if res[k+j] is None:
                                all_fixed = False
                                break
                            if res[k+j] != str2[j]:
                                is_match = False
                                break
                        if is_match and all_fixed:
                            possible = False
                            break
                if possible:
                    break
                else:
                    res[i] = None

    ans = "".join(res)
    # 最後驗證 (處理那些沒被填到但可能導致 F 違反的情況)
    for i in range(n):
        if str1[i] == 'F' and ans[i:i+m] == str2:
            return ""
