    memo = {}

    def get_dist(c1, c2):
        # 計算兩個字母之間的最小轉換距離 (考慮環狀轉移)
        diff = abs(ord(c1) - ord(c2))
        return min(diff, 26 - diff)

    def solve(i, j, rem_k):
        if i > j:
            return 0
        if i == j:
            return 1

        state = (i, j, rem_k)
        if state in memo:
            return memo[state]

        # 選項 1: 不包含 s[i]
        res = solve(i + 1, j, rem_k)

        # 選項 2: 不包含 s[j]
        res = max(res, solve(i, j - 1, rem_k))

        # 選項 3: 嘗試匹配 s[i] 和 s[j]
        dist = get_dist(s[i], s[j])
        if rem_k >= dist:
            res = max(res, 2 + solve(i + 1, j - 1, rem_k - dist))

        memo[state] = res
        return res

    return solve(0, n - 1, k)
```

這個問題可以簡化為：從 $m$ 列中選出 3 列，並從 $n$ 行中選出 3 行，然後在這些交叉點中選擇三個位置，使得每一行和每一列都只被佔用一次（類似於置換）。

由於矩陣大小最大為 $100 \times 100$，我們可以使用**動態規劃 (DP) 搭配 bitmask** 或者更簡單的 **Backtracking/Recursion with Memoization**。但因為只需要放 3 個棋子，最直接且高效的方法是：
1. 選出 3 列（從 $n$ 列中選）。
2. 在這些列中，嘗試所有可能的行分配組合（確保每列都不同，每行也不同）。

然而，為了保證最高效能並處理負數，我們只需要關注前幾大值。但最保險且符合邏輯的做法是使用遞迴搜尋：

```python
from typing import List

def maximumValueSum(board: List[List[int]]) -> int:
    m = len(board)
    n = len(board[0])

    # 為了優化，我們只考慮每列中最大的值所在的行，
    # 但因為題目要求「不攻擊」，所以必須考慮所有可能的組合。
    # 由於只需放 3 個棋子，我們可以使用遞迴搜尋。

    memo = {}

    def solve(row_idx, col_mask):
        # row_idx: 目前處理到第幾列 (0 到 n-1)
        # col_mask: 已使用的行索引的 bitmask
        if bin(col_mask).count('1') == 3:
            return 0
        if row_idx == n:
            return float('-inf')

        state = (row_idx, col_mask)
        if state in memo:
            return memo[state]

        # 選項 1: 不在這一列放棋子
        res = solve(row_idx + 1, col_mask)

        # 選項 2: 在這一列的某一行為放棋子 (若該行還沒被佔用)
        for r in range(m):
            if not (col_mask & (1 << r)):
                val = solve(row_idx + 1, col_mask | (1 << r))
                if val != float('-inf'):
                    res = max(res, board[r][row_idx] + val)

        memo[state] = res
        return res

    # 因為 m 可能很大 (100)，bitmask 1<<100 會爆記憶體。
    # 重新思考：我們只需要選出 3 列，並在這些列中選 3 個不同的行。

    # 正確的解法：
    # 選出 3 列 (C1, C2, C3) 從 n 列中選。
    # 對於這三列，找出所有可能的賦值組合 (R1, R2, R3) 其中 Ri 不同。

    max_sum = float('-inf')

    # 為了效率，我們只考慮每列中數值最大的前 3 個位置（因為最多只放 3 個）
    top_positions = []
    for c in range(n):
        cells = []
        for r in range(m):
            cells.append((board[r][c], r))
        # 取出數值最大的前 3 個位置即可
        cells.sort(key=lambda x: x[0], reverse=True)
        top_positions.append(cells[:3])

    # 從 top_positions 中選 3 列進行窮舉
    # 因為 n <= 100, 選 3 列的組合是 C(100, 3) = 161,700，可接受。
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # 從這三列中選出三個不同的行
                # 每列有最多 3 個候選位置，組合數極少
                for r1 in range(len(top_positions[i])):
                    val1, row1 = top_positions[i][r1]
                    for r2 in range(len(top_positions[j])):
                        val2, row2 = top_positions[j][r2]
                        if row1 == row2: continue
                        for r3 in range(len(top_positions[k])):
                            val3, row3 = top_positions[k][r3]
                            if row3 == row1 or row3 == row2: continue
                            max_sum = max(max_sum, val1 + val2 + val3)

    return int(max_sum)
```

**更簡單且符合 $O(N^3)$ 的實作（考慮到 $\text{m, n} \le 100$）：**
由於只需選 3 個，我們直接遍歷所有可能的 3 列組合，並在每列中找最優的行。

```python
from typing import List

def maximumValueSum(board: List[List[int]]) -> int:
    m = len(board)
    n = len(board[0])
    max_sum = float('-inf')

    # 預處理每列中最大的前三個位置，減少搜尋空間
    col_best = []
    for c in range(n):
        cells = []
        for r in range(m):
            cells.append((board[r][c], r))
        cells.sort(key=lambda x: x[0], reverse=True)
        col_best.append(cells[:3])

    # 窮舉三列組合
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # 在這三列中找三個不同的行
                for val1, r1 in col_best[i]:
                    for val2, r2 in col_best[j]:
                        if r1 == r2: continue
                        for val3, r3 in col_best[k]:
                            if r3 != r1 and r3 != r2:
                                if val1 + val2 + val3 > max_sum:
                                    max_sum = val1 + val2 + val3
    return int(max_sum)
