```python
def longestPalindrome(s: str, t: str) -> int:
    n, m = len(s), len(t)
    res = 0
    # Precompute all possible palindromes from s and t independently
    # Since substrings are small (max 30), we can just check them.

    def get_palindromes(string):
        pals = []
        for i in range(len(string)):
            for j in range(i, len(string) + 1):
                sub = string[i:j]
                if sub == sub[::-1]:
                    pals.append((sub, i, j))
        return pals

    s_pals = get_palindromes(s)
    t_pals = get_palindromes(t)

    # Max length from single string
    for p, _, _ in s_pals: res = max(res, len(p))
    for p, _, _ in t_pals: res = max(res, len(p))

    # Try combining a substring from s and a substring from t
    # The result is s[i:j] + t[k:l]. 
    # For this to be a palindrome, it must look like:
    # [prefix of s_sub][middle_pal][suffix of s_sub reversed]
    # But the problem says we pick ONE substring from s and ONE from t.
    # So result = s[i:j] + t[k:l].

    for i in range(n + 1):
        for j in range(i, n + 1):
            sub_s = s[i:j]
            for k in range(m + 1):
                for l in range(k, m + 1):
                    sub_t = t[k:l]
                    combined = sub_s + sub_t
                    if combined == combined[::-1]:
                        res = max(res, len(combined))
    return res
```

