```python
def longestPalindrome(s: str, t: str) -> int:
    max_len = 0
    n, m = len(s), len(t)

    # 預先找出 s 的所有子字串與 t 的所有子字串
    # 因為長度很小 (30)，O(N^2 * M^2) 是可行的
    for i in range(n + 1):
        for j in range(i, n + 1):
            sub_s = s[i:j]
            for k in range(m + 1):
                for l in range(k, m + 1):
                    sub_t = t[k:l]
                    combined = sub_s + sub_t

                    # 檢查是否為迴文
                    if combined == combined[::-1]:
                        max_len = max(max_len, len(combined))

    return max_len
