from collections import deque

def findSafeWalk(grid: list[list[int]], health: int) -> bool:
    m, n = len(grid), len(grid[0])
    # queue stores (r, c, current_health)
    queue = deque([(0, 0, health - grid[0][0])])
    visited = {(0, 0): health - grid[0][0]}

    while queue:
        r, c, h = queue.popleft()
        if r == m - 1 and c == n - 1:
            return h >= 1

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                nh = h - grid[nr][nc]
                if nh >= 1 and (nh > visited.get((nr, nc), -1)):
                    visited[(nr, nc)] = nh
                    queue.append((nr, nc, nh))
    return False
