def countPairs(nums: List[int]) -> int:
    def get_all_possible(n: int) -> set:
        s = list(str(n))
        results = {n}
        # Try all possible swaps within the string representation
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                if s[i] != s[j]:
                    new_s = list(s)
                    new_s[i], new_s[j] = new_s[j], new_s[i]
                    results.add(int("".join(new_s)))
        return results

    count = 0
    # Since the constraints are small (nums.length <= 100), 
    # an O(N^2 * K) approach is efficient enough.
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            x = nums[i]
            y = nums[j]

            # Check if x can become y or vice versa
            # This is equivalent to checking if one can be transformed into the other
            # by swapping digits at most once.
            s1 = list(str(x))
            s2 = list(str(y))

            if len(s1) != len(s2):
                continue

            # Count differences between s1 and s2
            diff_indices = []
            for k in range(len(s1)):
                if s1[k] != s2[k]:
                    diff_indices.append(k)

            # Case 0: Already equal
            if not diff_indices:
                count += 1
            # Case 1: One swap difference (exactly 2 positions different)
            elif len(diff_indices) == 2:
                idx1, idx2 = diff_indices
                if s1[idx1] == s2[idx2] and s1[idx2] == s2[idx1]:
                    count += 1

    return count
