from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    adj = [[] for _ in range(n)]

    # Pre-process to sets of unique integers
    sets = [set(p) for p in properties]

    # Build adjacency list
    for i in range(n):
        for j in range(i + 1, n):
            if len(sets[i].intersection(sets[j])) >= k:
                adj[i].append(j)
                adj[j].append(i)

    # BFS/DFS to find components
    visited = [False] * n
    count = 0
    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
    return count
