from typing import List
import math
from functools import reduce

def maxScore(nums: List[int]) -> int:
    # 輔助函式：計算 GCD
    def get_gcd(a, b):
        return math.gcd(a, b)

    # 輔助函式：計算 LCM
    def get_lcm(a, b):
        if a == 0 or b == 0: return 0
        return abs(a * b) // math.gcd(a, b)

    # 計算整個陣列的 score
    def calculate_score(arr):
        if not arr: return 0
        current_gcd = arr[0]
        current_lcm = arr[0]
        for i in range(1, len(arr)):
            current_gcd = get_gcd(current_gcd, arr[i])
            current_lcm = get_lcm(current_lcm, arr[i])
        return current_gcd * current_lcm

    # 情況 1: 不移除任何元素
    max_res = calculate_score(nums)

    # 情況 2: 嘗試移除每一個元素 (因為陣列長度最大僅 100，暴力解法可行)
    for i in range(len(nums)):
        temp_arr = nums[:i] + nums[i+1:]
        if temp_arr:
            max_res = max(max_res, calculate_score(temp_arr))
        else:
            # 移除後為空陣列的 score 為 0
            max_res = max(max_res, 0)

    return max_res
