        return res_gcd * res_lcm

    # Initial score (removing zero elements)
    max_s = calculate_score(nums)

    # Try removing each element one by one
    for i in range(len(nums)):
        current_arr = nums[:i] + nums[i+1:]
        if current_arr:
            max_s = max(max_s, calculate_score(current_arr))
        else:
            # If removing one element leaves an empty array
            max_s = max(max_s, 0)

